#include <bits/stdc++.h>
using namespace std;const int V=10000005,S=3205,U=1000000000;int h[V],t[S],x[1005],z[1005];long long e(long long a,long long b,long long&x,long long&y){if(!b)return x=1,y=0,a;long long d=e(b,a%b,y,x);y-=a/b*x;return d;}int b(int a,int c,int m){int s=sqrt(m-1)+1,A=1%m,z=0,r=-1;for(int i=0;i<s;i++)h[t[z++]=1LL*c*A%m]=i,A=1LL*A*a%m;int C=1%m;for(int i=1;i<=s&&r<0;i++)if(h[C=1LL*C*A%m]>=0)r=i*s-h[C];while(z)h[t[--z]]=-1;return r;}pair<int,int> q(int a,int c,int m){if(m==1)return {0,1};int o=0,A=1%m,d=1;long long X,Y;for(;;){int z=__gcd((long long)A*a%m,(long long)m);if(z==d)break;if(A==c)return {o,-1};o++;A=1LL*A*a%m;d=z;}if(c%d)return {-1,-1};m/=d;c/=d;A/=d;e(A,m,X,Y);c=1LL*c*((X%m+m)%m)%m;int v=b(a,c,m);if(v<0)return {-1,-1};int y=b(a,1%m,m);return {v%y+o,y};}bool m(long long&a,long long&n,long long b,long long p){long long x,y,g=e(n,p,x,y),d=b-a;if(d%g)return 0;long long z=p/g,k=(__int128)(d/g)*x%z;a=(a+(__int128)n*((k+z)%z))%(n*z);n*=z;return 1;}int main(){ios::sync_with_stdio(0);cin.tie(0);memset(h,-1,sizeof h);int n,X=-1,M=0;long long P=0,Q=1;cin>>n;for(int i=0,k,g,r;i<n;i++){cin>>k>>g>>r;auto a=q(k%g,r%g,g);x[i]=a.first;z[i]=a.second;if(x[i]<0)return cout<<"Impossible\n",0;if(z[i]<0)X=x[i];M=max(M,x[i]);}if(X>=0){for(int i=0;i<n;i++)if((z[i]<0&&X!=x[i])||(z[i]>=0&&(X<x[i]||(X-x[i])%z[i])))return cout<<"Impossible\n",0;return cout<<X<<'\n',0;}for(int i=0;i<n;i++){if(Q>U){if((P-x[i])%z[i])return cout<<"Impossible\n",0;}else if(!m(P,Q,x[i]%z[i],z[i]))return cout<<"Impossible\n",0;}if(P<M){if(Q>U)return cout<<"Impossible\n",0;P+=(M-P+Q-1)/Q*Q;}if(P>U)cout<<"Impossible\n";else cout<<P<<'\n';}
